import{_ as a,c as e,a1 as d,o as r}from"./chunks/framework.EpXtiTQS.js";const g=JSON.parse('{"title":"Yatori-go-core 开发手册","description":"","frontmatter":{},"headers":[],"relativePath":"yatori-go-core/dev/index.md","filePath":"yatori-go-core/dev/index.md"}'),o={name:"yatori-go-core/dev/index.md"};function i(n,t,s,l,c,p){return r(),e("div",null,t[0]||(t[0]=[d(`<h1 id="yatori-go-core-开发手册" tabindex="-1">Yatori-go-core 开发手册 <a class="header-anchor" href="#yatori-go-core-开发手册" aria-label="Permalink to &quot;Yatori-go-core 开发手册&quot;">​</a></h1><p>这本手册面向两类开发者：</p><ol><li><strong>想给 core 增加新平台</strong>：例如新增一个学校的网课平台、一个企业培训平台；</li><li><strong>想维护/修复现有平台适配器</strong>：例如接口变了、字段变了、登录流程变了。</li></ol><p>阅读完这本手册，你应该能够：</p><ul><li>理解 V2 的分层和依赖方向；</li><li>按统一规范新增一个平台适配器；</li><li>正确实现 <code>Client</code> 的每个方法；</li><li>正确映射 <code>Course / Node / Work / Exam / Session</code>；</li><li>正确使用 <code>Capabilities()</code> 和 <code>ErrUnsupported</code>；</li><li>写出不依赖真实账号的测试；</li><li>按仓库要求提交 PR。</li></ul><h2 id="先看整体架构" tabindex="-1">先看整体架构 <a class="header-anchor" href="#先看整体架构" aria-label="Permalink to &quot;先看整体架构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的业务代码</span></span>
<span class="line"><span>  └─ yatori.New / yatori.Client          ← 唯一公开入口</span></span>
<span class="line"><span>       └─ core                            ← 接口、模型、错误、能力位、注册表</span></span>
<span class="line"><span>            └─ internal/driver/&lt;平台&gt;      ← 你要新增/维护的适配器</span></span>
<span class="line"><span>                 ├─ internal/aggregation   ← 平台业务动作（旧代码）</span></span>
<span class="line"><span>                 └─ internal/api           ← 平台 HTTP 协议（旧代码）</span></span></code></pre></div><p>新增平台时，<strong>不要重写一套 HTTP 协议</strong>。优先复用 <code>internal/api</code> 和 <code>internal/aggregation</code> 里已有的实现；只有平台完全没有对应能力时，才新增底层代码。</p><h2 id="七条硬规则" tabindex="-1">七条硬规则 <a class="header-anchor" href="#七条硬规则" aria-label="Permalink to &quot;七条硬规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td>1. 公开面最小</td><td>只允许改 <code>yatori</code> 和 <code>core</code> 的公开 API；平台细节留在 <code>internal/</code></td></tr><tr><td>2. 适配器只做映射</td><td>不要把平台协议、加密、重试逻辑堆进 adapter</td></tr><tr><td>3. 不退出进程</td><td>新代码禁止 <code>log.Fatal</code>、<code>os.Exit</code>、<code>panic</code></td></tr><tr><td>4. 不依赖全局配置</td><td>只用 <code>core.Config</code>，不要读 <code>global.Config</code></td></tr><tr><td>5. 一个 Client 一个会话</td><td>公开方法必须用 <code>c.Lock()</code> 串行化</td></tr><tr><td>6. 能力位必须真实</td><td>没实现的方法不要设置对应能力位</td></tr><tr><td>7. 必须注册和文档化</td><td>平台常量、驱动注册、能力矩阵、账号参数、测试都要补齐</td></tr></tbody></table><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>文档</th><th>你会学到</th></tr></thead><tbody><tr><td>1</td><td><a href="/yatori-docs/yatori-go-core/dev/architecture.html">架构与分层</a></td><td>每个目录负责什么、依赖方向、注册表怎么工作</td></tr><tr><td>2</td><td><a href="/yatori-docs/yatori-go-core/dev/new-platform.html">新增平台完整教程</a></td><td>从零新增一个平台的可复制步骤</td></tr><tr><td>3</td><td><a href="/yatori-docs/yatori-go-core/dev/adapter-api.html">Adapter API 规范</a></td><td><code>Login/Courses/Tree/Study/...</code> 每个方法怎么写</td></tr><tr><td>4</td><td><a href="/yatori-docs/yatori-go-core/dev/data-mapping.html">数据映射规范</a></td><td><code>Course/Node/ID/Extra/Raw/Progress</code> 的约定</td></tr><tr><td>5</td><td><a href="/yatori-docs/yatori-go-core/dev/errors-and-capabilities.html">错误与能力位</a></td><td>错误怎么返回、能力位怎么设置</td></tr><tr><td>6</td><td><a href="/yatori-docs/yatori-go-core/dev/testing.html">测试与验收</a></td><td>不依赖真实账号的测试方法</td></tr><tr><td>7</td><td><a href="/yatori-docs/yatori-go-core/dev/style-and-pr.html">代码风格与 PR</a></td><td>命名、文档、提交、评审清单</td></tr><tr><td>8</td><td><a href="/yatori-docs/yatori-go-core/dev/faq.html">开发常见坑</a></td><td>最容易踩的 20 个坑</td></tr></tbody></table><h2 id="最小开发流程" tabindex="-1">最小开发流程 <a class="header-anchor" href="#最小开发流程" aria-label="Permalink to &quot;最小开发流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 调研平台接口</span></span>
<span class="line"><span>2. 在 core/platform.go 增加平台常量</span></span>
<span class="line"><span>3. 在 types.go 增加根包别名</span></span>
<span class="line"><span>4. 新建 internal/driver/&lt;name&gt;/adapter.go</span></span>
<span class="line"><span>5. 实现 New / Login / Courses / Tree / Study</span></span>
<span class="line"><span>6. 按需实现 Works / Exams / SignIn</span></span>
<span class="line"><span>7. 在 internal/driver/driver.go 注册</span></span>
<span class="line"><span>8. 写测试</span></span>
<span class="line"><span>9. 更新 README 和文档</span></span>
<span class="line"><span>10. gofmt / build / vet / test</span></span></code></pre></div><h2 id="什么时候该新增平台-什么时候该改现有平台" tabindex="-1">什么时候该新增平台，什么时候该改现有平台 <a class="header-anchor" href="#什么时候该新增平台-什么时候该改现有平台" aria-label="Permalink to &quot;什么时候该新增平台，什么时候该改现有平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>做法</th></tr></thead><tbody><tr><td>新学校、新公司、新域名，但接口和现有平台完全不同</td><td>新增平台</td></tr><tr><td>现有平台换了域名/登录页，但业务接口没变</td><td>改现有适配器的 URL/登录逻辑</td></tr><tr><td>现有平台新增了一个任务点类型</td><td>在现有适配器的 <code>Tree</code>/<code>Study</code> 里补映射</td></tr><tr><td>现有平台接口字段改名</td><td>先改 <code>internal/api</code>，再改 adapter 映射</td></tr><tr><td>只是业务层想换刷课节奏</td><td>不要改 core，改调用方的循环</td></tr></tbody></table><h2 id="先记住三个概念" tabindex="-1">先记住三个概念 <a class="header-anchor" href="#先记住三个概念" aria-label="Permalink to &quot;先记住三个概念&quot;">​</a></h2><h3 id="adapter" tabindex="-1">Adapter <a class="header-anchor" href="#adapter" aria-label="Permalink to &quot;Adapter&quot;">​</a></h3><p><code>internal/driver/&lt;平台&gt;</code> 里的代码。它实现 <code>core.Client</code>，把平台数据映射成统一模型。</p><h3 id="legacy" tabindex="-1">Legacy <a class="header-anchor" href="#legacy" aria-label="Permalink to &quot;Legacy&quot;">​</a></h3><p><code>internal/api</code> 和 <code>internal/aggregation</code> 里的旧代码。它们仍然是平台行为的“唯一真源”，adapter 尽量复用它们。</p><h3 id="capability" tabindex="-1">Capability <a class="header-anchor" href="#capability" aria-label="Permalink to &quot;Capability&quot;">​</a></h3><p>平台能力的位图。它告诉调用方“这个平台支持什么”，而不是“当前账号有什么数据”。</p><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><p>建议先读一遍：</p><ul><li><a href="/yatori-docs/yatori-go-core/docs.html">V2 总览</a></li><li><a href="/yatori-docs/yatori-go-core/v2/client-api.html">Client API</a></li><li><a href="/yatori-docs/yatori-go-core/v2/capabilities.html">能力与错误</a></li></ul><p>然后从 <a href="/yatori-docs/yatori-go-core/dev/architecture.html">架构与分层</a> 开始。</p>`,27)]))}const b=a(o,[["render",i]]);export{g as __pageData,b as default};
